package com.saucedemo.pages;
import com.saucedemo.config.TestConfig; import com.saucedemo.support.*; import org.openqa.selenium.By;
public class LoginPage {private static final By USERNAME=By.id("user-name"),PASSWORD=By.id("password"),LOGIN=By.id("login-button"),ERROR=By.cssSelector("[data-test='error']"); public void open(){DriverFactory.getDriver().get(TestConfig.baseUrl());Waits.visible(LOGIN);}public void login(String username,String password){Waits.visible(USERNAME).sendKeys(username);DriverFactory.getDriver().findElement(PASSWORD).sendKeys(password);Waits.clickable(LOGIN).click();}public String errorMessage(){return Waits.visible(ERROR).getText();}public boolean isDisplayed(){return Waits.visible(LOGIN).isDisplayed();}}
